window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bd7acdffd0e61bbd"]={"versions": [{"id": "FIG-bd7acdffd0e61bbd", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM 2.0 / UML-Prozessdiagramm (Methodology Process Pattern / Activity Breakdown) im Kontext der AUTOSAR-Methodik (AUTOSAR_TR_Methodology). Das Diagramm stellt die Dekomposition und Ablaufbeziehung des Use-Case-Musters „End To End Protection Wrapper Overview“ dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\"><li>Process Pattern (blaues Zyklus-/Aktivitätssymbol): <code>End To End Protection Wrapper Overview</code>.\n</li><li>Zusammengesetzte Aktivitäten (Compound Activities / Task-Container):\n<ul class=\"fig-list\"><li><code>Define E2E Protection Set</code>\n</li><li><code>Regenerate E2E Protection Wrapper</code>\n</li></ul>\n</li><li>Elementare Aktivitäten / Tasks (Pfeilsymbole nach rechts):\n<ul class=\"fig-list\"><li><code>Define E2E Protection Set for Swc</code> (zugeordnet zu <code>Define E2E Protection Set</code>)\n</li><li><code>Compile Atomic Software Component</code> (zugeordnet zu <code>Regenerate E2E Protection Wrapper</code>)\n</li><li><code>Generate E2E Protection Wrapper</code> (zugeordnet zu <code>Regenerate E2E Protection Wrapper</code>, unten rechts angeschnitten)\n</li></ul>\n</li><li>Beziehungen:\n<ul class=\"fig-list\"><li>Kompositionen / Verschachtelungen (<code>«nesting»</code> mit offener Raute):\n<ul class=\"fig-list\"><li><code>End To End Protection Wrapper Overview</code> schachtelt <code>Define E2E Protection Set</code> und <code>Regenerate E2E Protection Wrapper</code>\n</li><li><code>Define E2E Protection Set</code> schachtelt <code>Define E2E Protection Set for Swc</code>\n</li><li><code>Regenerate E2E Protection Wrapper</code> schachtelt <code>Compile Atomic Software Component</code> und <code>Generate E2E Protection Wrapper</code>\n</li></ul>\n</li><li>Kontrollfluss- / Vorgängerbeziehung (<code>«predecessor»</code>, gestrichelter Pfeil): Gerichtet von <code>Regenerate E2E Protection Wrapper</code> auf <code>Define E2E Protection Set</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Ausführungsreihenfolge wird über die «predecessor»-Abhängigkeit definiert:</p>\n<ol class=\"fig-list\"><li>Zunächst muss die Aktivität <code>Define E2E Protection Set</code> (mit dem Teilschritt <code>Define E2E Protection Set for Swc</code>) ausgeführt werden, um die E2E-Schutzkonfiguration und Profilparameter bereitzustellen.\n</li><li>Anschließend folgt die Aktivität <code>Regenerate E2E Protection Wrapper</code>, in welcher der Wrapper generiert (<code>Generate E2E Protection Wrapper</code>) und mit der atomaren Software-Komponente kompiliert wird (<code>Compile Atomic Software Component</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die methodische Struktur zur Absicherung von SWC-Kommunikation mittels E2E-Protection-Wrappern gemäß AUTOSAR-Methodologie. Werkzeuge zur E2E-Generierung und Integrationsumgebungen müssen die sequentielle Abhängigkeit sicherstellen: Eine Neugenerierung oder Kompilierung des E2E-Wrappers setzt zwingend einen gültig definierten E2E-Protection-Set auf Software-Komponenten-Ebene voraus.</p>"}, {"id": "FIG-08975c1d7b1f025a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM 2.0 / UML-Prozessdiagramm (Methodology Process Pattern / Activity Breakdown) im Kontext der AUTOSAR-Methodik (AUTOSAR_TR_Methodology). Das Diagramm stellt die Dekomposition und Ablaufbeziehung des Use-Case-Musters „End To End Protection Wrapper Overview“ dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\"><li>Process Pattern (blaues Zyklus-/Aktivitätssymbol): <code>End To End Protection Wrapper Overview</code>.\n</li><li>Zusammengesetzte Aktivitäten (Compound Activities / Task-Container):\n<ul class=\"fig-list\"><li><code>Define E2E Protection Set</code>\n</li><li><code>Regenerate E2E Protection Wrapper</code>\n</li></ul>\n</li><li>Elementare Aktivitäten / Tasks (Pfeilsymbole nach rechts):\n<ul class=\"fig-list\"><li><code>Define E2E Protection Set for Swc</code> (zugeordnet zu <code>Define E2E Protection Set</code>)\n</li><li><code>Compile Atomic Software Component</code> (zugeordnet zu <code>Regenerate E2E Protection Wrapper</code>)\n</li><li><code>Generate E2E Protection Wrapper</code> (zugeordnet zu <code>Regenerate E2E Protection Wrapper</code>, unten rechts angeschnitten)\n</li></ul>\n</li><li>Beziehungen:\n<ul class=\"fig-list\"><li>Kompositionen / Verschachtelungen (<code>«nesting»</code> mit offener Raute):\n<ul class=\"fig-list\"><li><code>End To End Protection Wrapper Overview</code> schachtelt <code>Define E2E Protection Set</code> und <code>Regenerate E2E Protection Wrapper</code>\n</li><li><code>Define E2E Protection Set</code> schachtelt <code>Define E2E Protection Set for Swc</code>\n</li><li><code>Regenerate E2E Protection Wrapper</code> schachtelt <code>Compile Atomic Software Component</code> und <code>Generate E2E Protection Wrapper</code>\n</li></ul>\n</li><li>Kontrollfluss- / Vorgängerbeziehung (<code>«predecessor»</code>, gestrichelter Pfeil): Gerichtet von <code>Regenerate E2E Protection Wrapper</code> auf <code>Define E2E Protection Set</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Ausführungsreihenfolge wird über die «predecessor»-Abhängigkeit definiert:</p>\n<ol class=\"fig-list\"><li>Zunächst muss die Aktivität <code>Define E2E Protection Set</code> (mit dem Teilschritt <code>Define E2E Protection Set for Swc</code>) ausgeführt werden, um die E2E-Schutzkonfiguration und Profilparameter bereitzustellen.\n</li><li>Anschließend folgt die Aktivität <code>Regenerate E2E Protection Wrapper</code>, in welcher der Wrapper generiert (<code>Generate E2E Protection Wrapper</code>) und mit der atomaren Software-Komponente kompiliert wird (<code>Compile Atomic Software Component</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die methodische Struktur zur Absicherung von SWC-Kommunikation mittels E2E-Protection-Wrappern gemäß AUTOSAR-Methodologie. Werkzeuge zur E2E-Generierung und Integrationsumgebungen müssen die sequentielle Abhängigkeit sicherstellen: Eine Neugenerierung oder Kompilierung des E2E-Wrappers setzt zwingend einen gültig definierten E2E-Protection-Set auf Software-Komponenten-Ebene voraus.</p>"}], "trans": [{"from": "FIG-bd7acdffd0e61bbd", "to": "FIG-08975c1d7b1f025a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
